// src/edge/botDetect.js
var BOT_UA = /googlebot|google-inspectiontool|bingbot|slurp|duckduckbot|baiduspider|yandexbot|facebookexternalhit|facebot|twitterbot|linkedinbot|embedly|whatsapp|telegrambot|applebot|semrushbot|ahrefsbot|mj12bot|dotbot|petalbot|yeti|naverbot|kakaotalk-scrap|kakaostory|daumoa|slackbot/i;
function isCrawlerRequest(request) {
  const url = new URL(request.url);
  if (url.searchParams.get("crawler") === "1") return true;
  if (request.headers.get("x-crawler-preview") === "1") return true;
  const ua = request.headers.get("user-agent") || "";
  return BOT_UA.test(ua);
}

// src/edge/edgeCrawlerSeoConstants.js
var DEFAULT_OG_IMAGE = "https://www.gateo.kr/og-image.png";
var GALLERY_SCHEMA_IMAGE_LIMIT = 8;
function getGalleryImageContentUrl(image) {
  if (!image || typeof image !== "object") return "";
  return image.urls?.regular || image.urls?.full || image.urls?.small || image.image_url || image.contentUrl || "";
}
function buildGalleryImageObjects(images, { placeName = "", limit = GALLERY_SCHEMA_IMAGE_LIMIT } = {}) {
  const list = Array.isArray(images) ? images : [];
  const objects = [];
  for (const image of list) {
    if (objects.length >= limit) break;
    const contentUrl = getGalleryImageContentUrl(image);
    if (!contentUrl) continue;
    const caption = image.alt_description || image.alt || (placeName ? `${placeName} travel photo` : "Travel photo");
    objects.push({
      "@type": "ImageObject",
      contentUrl,
      name: caption,
      caption
    });
  }
  return objects;
}
function buildPlaceGalleryJsonLd({ placeName, description, pageUrl, galleryImages, locale = "ko" }) {
  const imageObjects = buildGalleryImageObjects(galleryImages, { placeName });
  if (imageObjects.length === 0) return null;
  return {
    "@context": "https://schema.org",
    "@type": "ImageGallery",
    name: locale === "en" ? `${placeName} travel photos` : `${placeName} \uC5EC\uD589 \uC0AC\uC9C4`,
    description,
    url: pageUrl,
    image: imageObjects
  };
}
function buildCrawlerGalleryJsonLd(meta) {
  if (!meta?.galleryImages?.length) return null;
  return buildPlaceGalleryJsonLd({
    placeName: meta.placeName,
    description: meta.description,
    pageUrl: meta.canonicalUrl,
    galleryImages: meta.galleryImages,
    locale: meta.locale
  });
}

// src/shared/seo/socialOgImage.js
var DEFAULT_SITE_OG_IMAGE = "https://www.gateo.kr/og-image.png";
var WIKIMEDIA_HOST_RE = /(^|\.)wikimedia\.org$/i;
function isWikimediaOgImageUrl(url) {
  if (typeof url !== "string") return false;
  const trimmed = url.trim();
  if (!trimmed) return false;
  try {
    const host = new URL(trimmed).hostname;
    return WIKIMEDIA_HOST_RE.test(host);
  } catch {
    return /wikimedia\.org/i.test(trimmed);
  }
}
function resolveSocialShareImageUrl(url, fallback = DEFAULT_SITE_OG_IMAGE) {
  const trimmed = typeof url === "string" ? url.trim() : "";
  if (!trimmed) return fallback;
  if (isWikimediaOgImageUrl(trimmed)) return fallback;
  return trimmed;
}

// src/edge/injectCrawlerMeta.js
var SITE_NAME = "GATEO";
function escapeAttr(value) {
  return String(value || "").replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
}
function escapeHtml(value) {
  return String(value || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}
function escapeJsonForScript(value) {
  return JSON.stringify(value).replace(/</g, "\\u003c");
}
function galleryImagesForSchema(meta) {
  if (meta?.worldEventId) return null;
  const placeName = String(meta?.placeName || "").trim();
  if (!placeName) return null;
  if (Array.isArray(meta.galleryImages) && meta.galleryImages.length > 0) return meta.galleryImages;
  if (Array.isArray(meta.galleryImages)) return null;
  const ogImage = String(meta.ogImage || "").trim();
  if (!ogImage) return null;
  return [{ urls: { regular: ogImage } }];
}
function placeHref(slug, tab, locale) {
  const path = tab ? `/place/${slug}/${tab}` : `/place/${slug}`;
  return locale === "en" ? `${path}?lang=en` : path;
}
function replaceRootInnerHtml(html, inner) {
  const openMatch = html.match(/<div id="root">/i);
  if (!openMatch || openMatch.index == null) return html;
  const openEnd = openMatch.index + openMatch[0].length;
  let depth = 1;
  let i = openEnd;
  while (i < html.length && depth > 0) {
    const nextOpen = html.indexOf("<div", i);
    const nextClose = html.indexOf("</div>", i);
    if (nextClose === -1) return html;
    if (nextOpen !== -1 && nextOpen < nextClose) {
      depth += 1;
      i = nextOpen + 4;
      continue;
    }
    depth -= 1;
    if (depth === 0) {
      return `${html.slice(0, openMatch.index)}<div id="root">
${inner}
    </div>${html.slice(nextClose + 6)}`;
    }
    i = nextClose + 6;
  }
  return html;
}
function buildCrawlerPlaceBodyHtml(meta) {
  const slug = String(meta?.slug || "").trim();
  const placeName = String(meta?.placeName || "").trim();
  if (!slug || !placeName) return "";
  const locale = meta.locale === "en" ? "en" : "ko";
  const country = String(meta.countryName || "").trim();
  const destIata = String(meta.destIata || "").trim();
  const titlePlace = country ? `${placeName} (${country})` : placeName;
  const h1 = locale === "en" ? `${escapeHtml(titlePlace)} \u2014 travel guide &amp; attractions` : `${escapeHtml(titlePlace)} - \uC5EC\uD589 \uAC00\uC774\uB4DC &amp; \uBA85\uC18C`;
  const h2 = locale === "en" ? "Suggested routes and essentials (Gallery \xB7 Planner \xB7 AI docent)" : "\uCD94\uCC9C \uCF54\uC2A4 \uBC0F \uD544\uC218 \uC815\uBCF4 (\uAC24\uB7EC\uB9AC \xB7 \uD50C\uB798\uB108 \xB7 AI \uB3C4\uC2A8\uD2B8)";
  const galleryLabel = locale === "en" ? `${placeName} gallery` : `${placeName} \uAC24\uB7EC\uB9AC`;
  const plannerLabel = locale === "en" ? `${placeName} planner \xB7 stays \xB7 tours` : `${placeName} \uD50C\uB798\uB108 \xB7 \uC219\uC18C \xB7 \uD22C\uC5B4`;
  const wikiLabel = locale === "en" ? `${placeName} AI docent` : `${placeName} AI \uB3C4\uC2A8\uD2B8`;
  const airportLine = destIata ? locale === "en" ? `Nearby airport: ${destIata}` : `\uC778\uADFC \uACF5\uD56D: ${destIata}` : locale === "en" ? "Airport, stay, and tour links are in the planner." : "\uC778\uADFC \uACF5\uD56D \xB7 \uC219\uC18C \xB7 \uD22C\uC5B4 \uC548\uB0B4\uB294 \uD50C\uB798\uB108\uC5D0\uC11C \uD655\uC778\uD560 \uC218 \uC788\uC2B5\uB2C8\uB2E4.";
  return `      <!-- crawler-body-injected -->
      <article id="crawler-place-body">
        <h1>${h1}</h1>
        <p>${escapeHtml(meta.description)}</p>
        <p>${escapeHtml(meta.keywords)}</p>
        <h2>${h2}</h2>
        <nav>
          <ul>
            <li><a href="${escapeAttr(placeHref(slug, "gallery", locale))}">${escapeHtml(galleryLabel)}</a></li>
            <li><a href="${escapeAttr(placeHref(slug, "planner", locale))}">${escapeHtml(plannerLabel)}</a></li>
            <li><a href="${escapeAttr(placeHref(slug, "wiki", locale))}">${escapeHtml(wikiLabel)}</a></li>
          </ul>
          <p>${escapeHtml(airportLine)}</p>
        </nav>
      </article>`;
}
function buildCrawlerWorldEventBodyHtml(meta) {
  const id = String(meta?.worldEventId || "").trim();
  const headline = String(meta?.title || "").trim();
  if (!id || !headline) return "";
  return `      <!-- crawler-body-injected -->
      <article id="crawler-world-event-body">
        <h1>${escapeHtml(headline)}</h1>
        <p>${escapeHtml(meta.description)}</p>
      </article>`;
}
function buildCrawlerEditorialBodyHtml(meta) {
  const slug = String(meta?.editorialSlug || "").trim();
  const headline = String(meta?.articleTitle || meta?.title || "").trim();
  if (!slug || !headline) return "";
  const locale = meta.locale === "en" ? "en" : "ko";
  const placeName = String(meta?.placeName || "").trim();
  const placeSlug = String(meta?.placeSlug || "").trim();
  const placeHref2 = placeSlug ? locale === "en" ? `/place/${placeSlug}?lang=en` : `/place/${placeSlug}` : "";
  const placeLink = placeHref2 ? locale === "en" ? `<p><a href="${escapeAttr(placeHref2)}">${escapeHtml(placeName)} travel guide</a></p>` : `<p><a href="${escapeAttr(placeHref2)}">${escapeHtml(placeName)} \uC5EC\uD589 \uAC00\uC774\uB4DC</a></p>` : "";
  const h1 = locale === "en" ? `${escapeHtml(headline)} \u2014 GATEO editorial travelogue` : `${escapeHtml(headline)} \u2014 GATEO \uC5D0\uB514\uD130 \uAE30\uD589\uBB38`;
  return `      <!-- crawler-body-injected -->
      <article id="crawler-editorial-body">
        <h1>${h1}</h1>
        <p>${escapeHtml(meta.description)}</p>
        ${placeLink}
      </article>`;
}
function buildCrawlerHeadTags(meta) {
  const {
    locale,
    title,
    description,
    keywords,
    canonicalUrl,
    hreflangAlternates = [],
    ogImage,
    robotsNoIndex
  } = meta;
  const seoTitle = `${title} | ${SITE_NAME}`;
  const ogLocale = locale === "en" ? "en_US" : "ko_KR";
  const ogLocaleAlt = locale === "en" ? "ko_KR" : "en_US";
  const desc = escapeAttr(description);
  const kw = escapeAttr(keywords);
  const imageUrl = escapeAttr(resolveSocialShareImageUrl(ogImage || DEFAULT_OG_IMAGE));
  const hreflang = robotsNoIndex ? "" : hreflangAlternates.map(
    (alt) => `    <link rel="alternate" hreflang="${escapeAttr(alt.hreflang)}" href="${escapeAttr(alt.href)}" />`
  ).join("\n");
  const galleryPhotos = galleryImagesForSchema(meta);
  const gallerySchema = galleryPhotos ? buildCrawlerGalleryJsonLd({ ...meta, galleryImages: galleryPhotos }) : null;
  const jsonLdBlock = gallerySchema ? `
    <script type="application/ld+json" data-schema-type="ImageGallery">${escapeJsonForScript(gallerySchema)}</script>` : "";
  const robotsTag = robotsNoIndex ? `    <meta name="robots" content="noindex, nofollow" />
` : "";
  const canonicalTag = canonicalUrl ? `    <link rel="canonical" href="${escapeAttr(canonicalUrl)}" />
` : "";
  return `<!-- crawler-meta-injected -->
    <title>${escapeAttr(seoTitle)}</title>
    <meta name="description" content="${desc}" />
    <meta name="keywords" content="${kw}" />
${robotsTag}${canonicalTag}${hreflang ? `${hreflang}
` : ""}
    <meta property="og:type" content="website" />
    <meta property="og:url" content="${escapeAttr(canonicalUrl || "")}" />
    <meta property="og:title" content="${escapeAttr(seoTitle)}" />
    <meta property="og:description" content="${desc}" />
    <meta property="og:image" content="${imageUrl}" />
    <meta property="og:site_name" content="${SITE_NAME}" />
    <meta property="og:locale" content="${ogLocale}" />
    <meta property="og:locale:alternate" content="${ogLocaleAlt}" />
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:url" content="${escapeAttr(canonicalUrl || "")}" />
    <meta name="twitter:title" content="${escapeAttr(seoTitle)}" />
    <meta name="twitter:description" content="${desc}" />
    <meta name="twitter:image" content="${imageUrl}" />${jsonLdBlock}`;
}
function injectCrawlerMetaIntoHtml(html, meta) {
  const headTags = buildCrawlerHeadTags(meta);
  let out = html.replace(/<html[^>]*>/i, `<html lang="${escapeAttr(meta.locale)}">`);
  out = out.replace(/<title>[\s\S]*?<\/title>/gi, "");
  out = out.replace(/<meta\b[^>]*\bname=["']description["'][^>]*>/gi, "");
  out = out.replace(/<meta\b[^>]*\bname=["']keywords["'][^>]*>/gi, "");
  out = out.replace(/<link\b[^>]*\brel=["']canonical["'][^>]*>/gi, "");
  out = out.replace(/<link\b[^>]*\brel=["']alternate["'][^>]*\bhreflang=["'][^"']+["'][^>]*>/gi, "");
  out = out.replace(/<meta\b[^>]*\bproperty=["']og:[^"']+["'][^>]*>/gi, "");
  out = out.replace(/<meta\b[^>]*\bname=["']twitter:[^"']+["'][^>]*>/gi, "");
  out = out.replace(
    /<script type="application\/ld\+json" data-schema-type="ImageGallery">[\s\S]*?<\/script>/gi,
    ""
  );
  out = out.replace(/<!-- crawler-meta-injected -->[\s\S]*?(?=<meta|<link rel="icon"|<script)/i, "");
  out = out.replace(/<head>/i, `<head>
${headTags}
`);
  const bodyHtml = meta?.worldEventId ? buildCrawlerWorldEventBodyHtml(meta) : meta?.editorialSlug ? buildCrawlerEditorialBodyHtml(meta) : buildCrawlerPlaceBodyHtml(meta);
  if (bodyHtml) {
    out = replaceRootInnerHtml(out, bodyHtml);
  }
  return out;
}

// src/edge/editorialSlug.js
function isEditorialSlugSafe(slug) {
  const value = String(slug || "").trim();
  if (!value || value.length > 120) return false;
  return /^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value);
}

// src/edge/editorialSupabase.js
var DEFAULT_TIMEOUT_MS = 1500;
function getEditorialSupabaseConfig() {
  const url = String(process.env.VITE_SUPABASE_URL || "").trim();
  const key = String(process.env.VITE_SUPABASE_ANON_KEY || "").trim();
  if (!url || !key) return null;
  return { url, key };
}
async function fetchPublishedEditorialBySlug(slug, options = {}) {
  if (!isEditorialSlugSafe(slug)) return null;
  const cfg = getEditorialSupabaseConfig();
  if (!cfg) return null;
  const select = "slug,title,dek,content,images,disclosure_badge,published_at,place_slug,locale";
  const endpoint = `${cfg.url}/rest/v1/reports?select=${encodeURIComponent(select)}&is_editorial=eq.true&status=eq.published&is_deleted=eq.false&slug=eq.${encodeURIComponent(slug)}&limit=1`;
  const fetchImpl = options.fetchImpl || fetch;
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  try {
    const res = await fetchImpl(endpoint, {
      headers: { apikey: cfg.key, Authorization: `Bearer ${cfg.key}` },
      signal: AbortSignal.timeout(timeoutMs)
    });
    if (!res.ok) return null;
    const rows = await res.json();
    if (!Array.isArray(rows) || !rows[0]?.slug || !rows[0]?.title) return null;
    return rows[0];
  } catch {
    return null;
  }
}
async function fetchPublishedEditorialIndex(options = {}) {
  const cfg = getEditorialSupabaseConfig();
  if (!cfg) return [];
  const endpoint = `${cfg.url}/rest/v1/reports?select=${encodeURIComponent("slug,published_at")}&is_editorial=eq.true&status=eq.published&is_deleted=eq.false&order=published_at.desc`;
  const fetchImpl = options.fetchImpl || fetch;
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  try {
    const res = await fetchImpl(endpoint, {
      headers: { apikey: cfg.key, Authorization: `Bearer ${cfg.key}` },
      signal: AbortSignal.timeout(timeoutMs)
    });
    if (!res.ok) return [];
    const rows = await res.json();
    if (!Array.isArray(rows)) return [];
    return rows.filter((row) => isEditorialSlugSafe(row?.slug));
  } catch {
    return [];
  }
}

