// src/pages/Home/lib/exploreCategorySeo.js
var EXPLORE_SEO_CONTINENTS = [
  "asia",
  "europe",
  "north_america",
  "south_america",
  "oceania",
  "africa"
];
var EXPLORE_SEO_CATEGORIES = ["paradise", "culture", "urban", "nature", "adventure"];
function isExploreSeoContinent(id) {
  return EXPLORE_SEO_CONTINENTS.includes(id);
}
function isExploreSeoCategory(id) {
  return EXPLORE_SEO_CATEGORIES.includes(id);
}

