// src/shared/seo/placeCanonicalPath.js
var INDEXED_PLACE_TABS = /* @__PURE__ */ new Set(["gallery", "planner", "wiki"]);
var ROUTER_PLACE_TABS = new Set(Object.values(PLACE_URL_TAB_BY_MEDIA_MODE));
function isPlaceRootAliasTab(tab) {
  const key = String(tab ?? "").trim().toLowerCase();
  return ROUTER_PLACE_TABS.has(key) && !INDEXED_PLACE_TABS.has(key);
}

// src/edge/placeMetaDescription.js
var META_DESCRIPTION_MAX2 = 155;
